import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Strategy C — Runtime Module Loading as Handler Interpreted Ops","description":"","frontmatter":{"title":"Strategy C — Runtime Module Loading as Handler Interpreted Ops","type":"adr","date":"2026-10-16T00:00:00.000Z","status":"proposed","status_note":"Proposed\\n\\nBuilds on [ADR-0069 — Files Are Arrows](./0069-arrow-native-modules.md) (§5 Strategy C).\\nReferences [ADR-0008 — Pluggable LSP](./0008-pluggable-lsp-language-agnostic-server.md)."},"headers":[],"relativePath":"handl/project/adrs/0009-strategy-c-runtime-module-loading.md","filePath":"vendored/handl/project/adrs/0009-strategy-c-runtime-module-loading.md"}`),a={name:`handl/project/adrs/0009-strategy-c-runtime-module-loading.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0009-strategy-c-—-runtime-module-loading-as-handler-interpreted-ops" tabindex="-1">ADR-0009: Strategy C — Runtime Module Loading as Handler Interpreted Ops <a class="header-anchor" href="#adr-0009-strategy-c-—-runtime-module-loading-as-handler-interpreted-ops" aria-label="Permalink to “ADR-0009: Strategy C — Runtime Module Loading as Handler Interpreted Ops”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Strategy C is <strong>not a separate strategy</strong>. It is what happens when you don&#39;t normalise <code>module_ref</code>/<code>project</code> away and the handler interprets them. The handler&#39;s operation table is the opt-in mechanism.</p><h3 id="_1-the-ops-are-the-mechanism" tabindex="-1">1. The ops are the mechanism <a class="header-anchor" href="#_1-the-ops-are-the-mechanism" aria-label="Permalink to “1. The ops are the mechanism”">​</a></h3><p><code>module_ref</code> and <code>project</code> are <code>arr</code> ops, already emitted by <code>rewrite_imports</code> in the parser. They are already in the <code>Scheme</code> graph. No new <code>Scheme</code> variants, no new language constructs.</p><p>A handler with operation clauses for these ops:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>handle module_ref(path) {</span></span>
<span class="line"><span>  -- resolve path, load file, evaluate, return record of public arrows</span></span>
<span class="line"><span>  loader.load(path) &gt;&gt;&gt; evaluate</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>handle project(record, field) {</span></span>
<span class="line"><span>  -- extract field from record</span></span>
<span class="line"><span>  record.field</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>A handler without these clauses: the graph must be normalised (Strategy A/B) before interpretation, or the handler refuses with &quot;unknown op: module_ref&quot;.</p><h3 id="_2-no-directive-no-capability-flag" tabindex="-1">2. No directive, no capability flag <a class="header-anchor" href="#_2-no-directive-no-capability-flag" aria-label="Permalink to “2. No directive, no capability flag”">​</a></h3><p>The original Strategy C framing proposed:</p><ul><li>A <code>-- @strategy runtime</code> program directive → <strong>removed.</strong> The handler decides by having (or not having) clauses.</li><li>A <code>supports_runtime_loading</code> handler capability → <strong>removed.</strong> That&#39;s just &quot;does the operation table include <code>module_ref</code>?&quot;</li><li>A separate &quot;Strategy C&quot; code path → <strong>removed.</strong> It&#39;s the same graph, interpreted by a handler that handles the ops.</li></ul><h3 id="_3-governance-is-handler-configuration" tabindex="-1">3. Governance is handler configuration <a class="header-anchor" href="#_3-governance-is-handler-configuration" aria-label="Permalink to “3. Governance is handler configuration”">​</a></h3><p>The handler&#39;s <code>module_ref</code> clause is where governance lives:</p><ul><li><strong>Path allowlist:</strong> the clause checks <code>path</code> against <code>allowed_roots</code> before resolving. Paths outside → error.</li><li><strong>Depth limit:</strong> the clause tracks the active load stack. Exceeds <code>max_depth</code> → error.</li><li><strong>No network by default:</strong> which resolvers are wired into the handler&#39;s loader is handler config. <code>FileResolver</code> only by default; <code>NetworkResolver</code> only if explicitly configured.</li><li><strong>Cycle detection at runtime:</strong> the loader tracks the active load stack. A cycle → <code>LoadError::Cycle</code>, not an infinite loop.</li></ul><p>This is handler config — the same place every other capability is governed. No workspace-level policy file, no program-level directive.</p><h3 id="_4-static-analysis-passes-no-execution-needed" tabindex="-1">4. Static analysis passes (no execution needed) <a class="header-anchor" href="#_4-static-analysis-passes-no-execution-needed" aria-label="Permalink to “4. Static analysis passes (no execution needed)”">​</a></h3><p>Two static passes over the <code>Scheme</code> graph, both already implementable with the current op encoding:</p><p><strong>Cycle detection:</strong></p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>fn detect_cycles(scheme: &amp;Scheme) -&gt; Result&lt;(), CycleError&gt;</span></span>
<span class="line"><span>  - walk scheme, collect all module_ref(path) nodes</span></span>
<span class="line"><span>  - build import graph: path → set of paths it imports</span></span>
<span class="line"><span>  - detect cycles via DFS</span></span></code></pre></div><p><strong>Contract inference:</strong></p><ul><li>Register <code>module_ref</code> and <code>project</code> in <code>ContractRegistry</code> with permissive contracts.</li><li>For tighter contracts: load referenced modules&#39; contracts (via <code>ModuleLoader</code>&#39;s contract cache), compose without inlining code.</li><li><code>infer_refinement</code> works on the whole graph without modification.</li></ul><h3 id="_5-the-scheme-variant-question" tabindex="-1">5. The <code>Scheme</code> variant question <a class="header-anchor" href="#_5-the-scheme-variant-question" aria-label="Permalink to “5. The Scheme variant question”">​</a></h3><p><code>module_ref</code>/<code>project</code> now reach interpretation under this design. They remain <code>arr</code> ops, not real <code>Scheme</code> variants. The handler matches on <code>op: &quot;module_ref&quot;</code> stringly, same as every other op.</p><p>Graduate to real <code>Scheme::ModuleRef</code>/<code>Scheme::Project</code> variants only if:</p><ul><li>A second handler needs to interpret them (one handler matching a string is fine; two duplicating the convention is the signal), AND</li><li>The stringly-typed matching causes real problems (bugs, missed cases).</li></ul><p>Until then, the closed kernel principle (ADR: closed arrow calculus kernel) holds: six combinators, no more.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>ADR-0069 defines three normalisation strategies for module imports. Strategies A (compile-time desugar) and B (whole-program flattening) are implemented: they eliminate <code>module_ref</code>/<code>project</code> ops from the <code>Scheme</code> graph before the handler sees them. Strategy C (runtime module loading) is described but not implemented.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>No new language mechanism. Module loading uses the existing handler <code>op</code> machinery. Zero new concepts.</li><li>Opt-in is automatic: a handler that handles <code>module_ref</code>/<code>project</code> does runtime loading; one that doesn&#39;t doesn&#39;t. No configuration beyond the operation table.</li><li>Static analysis is preserved. Cycle detection and contract inference work on the graph without execution.</li><li>Enables REPLs, hot-reload, plugin systems, dynamic loading — all via handler clauses, no special-casing.</li><li>Composes with Strategies A/B: normalise when you want a closed artifact, don&#39;t normalise when you want runtime loading. Same graph, different handler.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0009-strategy-c-runtime-module-loading.html"><code>design/0009-strategy-c-runtime-module-loading.md</code></a>.</p>`,36)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};